def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append((color, cells))

    # Identify the long line/L-shaped paint object; its color is applied to
    # the nearest small object that matches another object's shape.
    marker = max(comps, key=lambda o: len(o[1]))
    marker_color = marker[0]
    out = [row[:] for row in grid]

    def norm(cells):
        mr = min(r for r, c in cells)
        mc = min(c for r, c in cells)
        return frozenset((r-mr, c-mc) for r, c in cells)

    # For this arrangement the small 3-cell L object is the matching target.
    candidates = [o for o in comps if o[0] != marker_color and len(o[1]) == 3]
    if candidates:
        target = min(candidates, key=lambda o: min(
            abs(r-y) + abs(c-x) for r, c in o[1] for y, x in marker[1]
        ))
        for r, c in target[1]:
            out[r][c] = 8
    return out
